private void permute(int[] nums, int start, List<Integer> current, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        permute(nums, i + 1, current, permutations);
        current.remove(current.size() - 1);
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> remaining = new ArrayList<>(nums.length - 1);
        for (int j = 0; j < nums.length; j++) {
            if (i != j) {
                remaining.add(nums[j]);
            }
        }
        List<List<Integer>> subResult = permute(remaining.toArray());
        for (List<Integer> subPerm : subResult) {
            subPerm.add(0, num);
            result.add(subPerm);
        }
    }
    return result;
}

