public int findLargestSubstring(List<String> strings) {
    // Initialize largest substring length as 0
    int largestSubstringLength = 0;

    // Loop through each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // If the string length is greater than the largest substring length, update the largest substring length
        if (stringLength > largestSubstringLength) {
            largestSubstringLength = stringLength;
        }

        // If the string length is greater than half of the largest substring length, then the inverse of the string cannot be a substring
        if (stringLength > largestSubstringLength / 2) {
            continue;
        }

        // Check if the inverse of the string is a substring of any of the other strings
        int idx = 0;
        while (idx < stringLength) {
            // Get the substring of the string from the current index to the end
            String substring = string.substring(idx);

            // Check if the substring is present in any of the other strings
            for (String otherString : strings) {
                if (otherString.contains(substring)) {
                    // If the substring is present, then update the largest substring length
                    largestSubstringLength = Math.max(largestSubstringLength, stringLength);
                    break;
                }
            }

            // Increment the index by the length of the substring
            idx += substring.length();
        }
    }

    return largestSubstringLength;
}

