public static String convertDatesToWeekdays(String date) {
    SimpleDateFormat format = new SimpleDateFormat("MM dd yyyy");
    Date inputDate = format.parse(date);
    Calendar calendar = new GregorianCalendar();
    calendar.setTime(inputDate);
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);
    switch (weekday) {
        case Calendar.SUNDAY:
            return date + " is a Sunday";
        case Calendar.MONDAY:
            return date + " is a Monday";
        case Calendar.TUESDAY:
            return date + " is a Tuesday";
        case Calendar.WEDNESDAY:
            return date + " is a Wednesday";
        case Calendar.THURDAY:
            return date + " is a Thursday";
        case Calendar.FRIDAY:
            return date + " is a Friday";
        case Calendar.SATURDAY:
            return date + " is a Saturday";
        default:
            return "Invalid weekday";
    }
}

