private int findRotatedPivot(int[] nums) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } else if (nums[mid] < nums[right]) {
            right = mid - 1;
        } else {
            right--;
        }
    }
    return left == nums.length ? -1 : left;
}

