    if (Arrays.binarySearch(nums, target) >= 0) {
        return Arrays.binarySearch(nums, target);
    }

    // Search for the target value in the rotated array
    int pivot = 0;
    while (pivot < nums.length && nums[pivot] != target) {
        pivot++;
    }

    // If the pivot is found, return its index
    if (pivot < nums.length) {
        return pivot;
    }

    // If the pivot is not found, search the left and right parts of the array
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
