public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the smallest 5% and largest 5% of elements
    int smallest5Percent = (int) (arr.length * 0.05);
    int largest5Percent = arr.length - smallest5Percent;

    // Calculate the average of the remaining elements
    double mean = 0.0;
    for (int i = smallest5Percent; i < largest5Percent; i++) {
        mean += arr[i];
    }
    mean /= (arr.length - 2 * smallest5Percent);

    return mean;
}

public double trimMean(int[] arr) {
	// Sort the array in ascending order
	Arrays.sort(arr);

	// Remove the smallest 5% of elements
	int min = (int) Math.ceil(arr.length * 0.05);
	for (int i = 0; i < min; i++) {
		arr[i] = 0;
	}

	// Remove the largest 5% of elements
	int max = (int) Math.ceil(arr.length * 0.95);
	for (int i = arr.length - 1; i > max; i--) {
		arr[i] = 0;
	}

	// Calculate the mean
	double mean = 0;
	for (int i = 0; i < arr.length; i++) {
		mean += arr[i];
	}
	mean /= arr.length;

	return mean;
}

public double trimMean(int[] arr) {

