  Integer[] sortedArr = new Integer[arr.length];
  for (int i = 0; i < arr.length; i++) {
      sortedArr[i] = arr[i];
  }
  Arrays.sort(sortedArr);

  // calculate the indices of the smallest and largest 5% elements
  int smallest5Pct = (int) Math.max(Math.ceil(arr.length * 0.05), 1);
  int largest5Pct = arr.length - smallest5Pct;

  // remove the smallest and largest 5% elements from the sorted array
  Integer[] trimmedArr = new Integer[arr.length - 2 * smallest5Pct];
  for (int i = smallest5Pct; i < largest5Pct; i++) {
      trimmedArr[i - smallest5Pct] = sortedArr[i];
  }

  // calculate the mean of the remaining elements
  int total = 0;
  for (int elem : trimmedArr) {
      total += elem;
  }
  return (double) total / (trimmedArr.length);

}

public double trimMean(int[] arr) {
