    Arrays.sort(arr);

    // Find the 5% lowest and 5% highest values
    int minIndex = (int) (arr.length * 0.05);
    int maxIndex = arr.length - (int) (arr.length * 0.05);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = minIndex; i < maxIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = sum / (arr.length - 2 * minIndex);

    // Return the rounded mean with an error within 10^-5
    return Math.round(mean * 1e5) / 1e5;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the smallest and largest ends
    int numElementsToRemove = (int) Math.ceil(arr.length * 0.05);

    // Remove the smallest and largest elements
    int[] trimmedArray = Arrays.copyOfRange(arr, numElementsToRemove, arr.length - numElementsToRemove);

    // Calculate the mean of the trimmed array
    double mean = trimmedArray.stream().mapToDouble(d -> d).average().orElse(0.0);

    // Output the mean with an error within 10^-5
    return Math.round(mean * Math.pow(10, 5)) / Math.pow(10, 5);
}

public boolean canArrange(int[] arr, int k) {
    // check if the input array is empty or divisible by k
    if (arr.length == 0 || arr.length % k == 0) {
        return false;
    }

    // create a map to store the combinations
    Map<Integer, Integer> combinations = new HashMap<>();

    // iterate over the array and divide each element by k
    for (int i = 0; i < arr.length; i++) {
        int div = arr[i] / k;
        // check if the result is already in the map
        if (combinations.containsKey(div)) {
            // if it is, increment the count
            combinations.put(div, combinations.get(div) + 1);
        } else {
            // if it's not, add it to the map
            combinations.put(div, 1);
        }
    }

    // check if there are n/2 pairs that sum up to the same value
    int count = 0;
    for (int key: combinations.keySet()) {
        if (combinations.get(key) == arr.length / 2) {
            count++;
        }
    }
    return count == 1;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to store the sum of each pair
    Map<Integer, Integer> pairs = new HashMap<>();

    // Iterate over the array
    for (int i = 0; i < arr.length - 1; i++) {
        // Calculate the sum of the current pair
        int sum = arr[i] + arr[i + 1];

        // Check if the sum is divisible by k
        if (sum % k == 0) {
            // Add the pair to the hash map if it is divisible by k
            pairs.put(sum, pairs.getOrDefault(sum, 0) + 1);
        }
    }

    // Check if there are (arr.length / 2) pairs in the hash map
    return pairs.size() == arr.length / 2;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the divisor is valid
    if (k <= 1) return false;

    // Calculate the number of pairs that can be formed
    int n = arr.length;
    int numPairs = n / 2;

    // Initialize the map to store the count of each number
    Map<Integer, Integer> countMap = new HashMap<>();
    for (int num : arr) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    // Check if the count of each number is divisible by k
    for (int count : countMap.values()) {
        if (count % k != 0) return false;
    }

    // Check if the sum of each pair is divisible by the divisor
    for (int i = 0; i < numPairs; i++) {
        int pairSum = arr[i] + arr[i + numPairs];
        if (pairSum % k != 0) return false;
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) {
        return false;
    }

    // Initialize a map to store the counts of each number in the array
    Map<Integer, Integer> countMap = new HashMap<>();
    for (int num : arr) {
        if (!countMap.containsKey(num)) {
            countMap.put(num, 0);
        }
        countMap.put(num, countMap.get(num) + 1);
    }

    // Check if it is possible to divide the array into n/2 pairs
    int pairCount = 0;
    for (int num : countMap.keySet()) {
        if (countMap.get(num) >= 2) {
            pairCount += countMap.get(num) / 2;
        }
    }
    return pairCount >= n/2;
}

public boolean canArrange(int[] arr, int k) {
  // check if k is a factor of the sum of the entire array
  if (k % arr.length != 0) return false;

  // initialize a hash set to keep track of already seen elements
  Set<Integer> seen = new HashSet<>();

  // loop through the array
  for (int i = 0; i < arr.length; i++) {
    // if the current element is already in the set, return false
    if (seen.contains(arr[i])) return false;

    // otherwise, add the current element to the set
    seen.add(arr[i]);

    // if the size of the set is equal to k, remove the smallest element from the set
    if (seen.size() == k) {
      seen.remove(Collections.min(seen));
    }
  }

  // if the size of the set is 0, return true
  return seen.size() == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the time array
    int[] time = new int[n];
    for (int i = 0; i < n; i++) {
        time[i] = Integer.MAX_VALUE;
    }

    // Initialize the queue
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    time[0] = 0;

    // BFS
    while (!queue.isEmpty()) {
        int curr = queue.remove();
        for (int i = 0; i < edges.length; i++) {
            int node = edges[i][0] == curr ? edges[i][1] : edges[i][0];
            if (hasApple[node] && time[node] > time[curr] + 1) {
                time[node] = time[curr] + 1;
                queue.add(node);
            }
        }
    }

    // Find the minimum time
    int minTime = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && time[i] < minTime) {
            minTime = time[i];
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph and a boolean array to keep track of visited nodes
    Graph graph = new Graph(n);
    boolean[] visited = new boolean[n];

    // Iterate over the edges and add them to the graph
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Initialize a priority queue and a distance array to keep track of the shortest distance to each node
    PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);

    // Set the distance of node 0 to 0 and add it to the priority queue
    distance[0] = 0;
    pq.offer(new int[] {0, 0});

    // Loop until the priority queue is empty
    while (!pq.isEmpty()) {
        // Get the node with the smallest distance from the priority queue
        int[] current = pq.poll();
        int node = current[0];
        int distanceToNode = current[1];

        // If the node has already been visited, skip it
        if (visited[node]) {
            continue;
        }

        // Mark the node as visited
        visited[node] = true;

        // If the node has an apple, return the distance to it
        if (hasApple[node]) {
            return distanceToNode;
        }

        // Get the neighbors of the node
        for (int neighbor : graph.getNeighbors(node)) {
            // Calculate the distance to the neighbor from the current node
            int neighborDistance = distanceToNode + graph.getWeight(node, neighbor);

            // If the distance to the neighbor is shorter than the current distance, update it
            if (neighborDistance < distance[neighbor]) {
                distance[neighbor] = neighborDistance;
                pq.offer(new int[] {neighbor, neighborDistance});
            }
        }
    }

    // If all nodes have been visited and no apples have been found, return -1
    return -1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[0] = 0;

    int[] time = new int[n];
    Arrays.fill(time, -1);
    time[0] = 0;

    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time[i] = 0;
        }
    }

    for (int j = 0; j < n; j++) {
        int u = j;
        int distU = dist[u];
        if (distU != -1) {
            for (int i = 0; i < edges.length; i++) {
                int v = edges[i][0] == u ? edges[i][1] : edges[i][0];
                int w = edges[i][1] == u ? edges[i][0] : edges[i][1];
                int distV = dist[v];
                int distW = dist[w];
                if (distV == -1 || distW == -1) continue;
                int timeV = time[v];
                int timeW = time[w];
                int timeU = Math.max(timeV, timeW) + 1;
                if (timeU < distW) {
                    dist[v] = timeV;
                    dist[w] = timeW;
                    time[v] = timeU;
                    time[w] = timeU;
                }
            }
        }
    }

    int minTime = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime = Math.min(minTime, time[i]);
        }
    }

    return minTime;
}

