private void visit(int node, int time, boolean[] visited, boolean[] hasApple) {
    // If the node is already visited, return
    if (visited[node]) {
        return;
    }

    // Mark the node as visited
    visited[node] = true;

    // Increment the time
    time++;

    // If the node has an apple, return the current time
    if (hasApple[node]) {
        return time;
    }

    // Visit the neighbors of the current node
    for (int neighbor : edges[node]) {
        visit(neighbor, time, visited, hasApple);
    }
}

public String sortString(String s) {
  StringBuilder sb = new StringBuilder();
  while (s.length() > 0) {
    // 1. Pick the smallest character from s and append it to the result.
    int smallest = 0;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) < s.charAt(smallest)) {
        smallest = i;
      }
    }
    sb.append(s.charAt(smallest));
    s = s.substring(0, smallest) + s.substring(smallest + 1);

    // 2. Pick the smallest character from s which is greater than the last appended character to the result and append it.
    int smallestGreaterThanLast = -1;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) > sb.charAt(sb.length() - 1) &&
          (smallestGreaterThanLast < 0 || s.charAt(i) < s.charAt(smallestGreaterThanLast))) {
        smallestGreaterThanLast = i;
      }
    }
    if (smallestGreaterThanLast >= 0) {
      sb.append(s.charAt(smallestGreaterThanLast));
      s = s.substring(0, smallestGreaterThanLast) + s.substring(smallestGreaterThanLast + 1);
    }

    // 3. Repeat step 2 until you cannot pick more characters.
    while (s.length() > 0) {
      // 4. Pick the largest character from s and append it to the result.
      int largest = 0;
      for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) > s.charAt(largest)) {
          largest = i;
        }
      }
      sb.append(s.charAt(largest));
      s = s.substring(0, largest) + s.substring(largest + 1);

      // 5. Pick the largest character from s which is smaller than the last appended character to the result and append it.
      int largestSmallerThanLast = -1;
      for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) < sb.charAt(sb.length() - 1) &&
            (largestSmallerThanLast < 0 || s.charAt(i) > s.charAt(largestSmallerThanLast))) {
          largestSmallerThanLast = i;
        }
      }
      if (largestSmallerThanLast >= 0) {
        sb.append(s.charAt(largestSmallerThanLast));
        s = s.substring(0, largestSmallerThanLast) + s.substring(largestSmallerThanLast + 1);
      }
    }
  }
  return sb.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();

    // step 1
    char smallest = s.charAt(0);
    result.append(smallest);

    // step 2
    int smallestIndex = 1;
    while (smallestIndex < s.length()) {
        char nextSmallest = s.charAt(smallestIndex);
        if (nextSmallest > smallest) {
            result.append(nextSmallest);
            smallest = nextSmallest;
        }
        smallestIndex++;
    }

    // step 3
    char largest = s.charAt(s.length() - 1);
    result.append(largest);

    // step 4
    int largestIndex = s.length() - 2;
    while (largestIndex >= 0) {
        char nextLargest = s.charAt(largestIndex);
        if (nextLargest < largest) {
            result.append(nextLargest);
            largest = nextLargest;
        }
        largestIndex--;
    }

    // step 5
    while (smallestIndex < s.length()) {
        char nextSmallest = s.charAt(smallestIndex);
        if (nextSmallest > smallest) {
            result.append(nextSmallest);
            smallest = nextSmallest;
        }
        smallestIndex++;
    }

    // step 6
    while (largestIndex >= 0) {
        char nextLargest = s.charAt(largestIndex);
        if (nextLargest < largest) {
            result.append(nextLargest);
            largest = nextLargest;
        }
        largestIndex--;
    }

    return result.toString();
}

public String sortString(String s) {
    String result = "";
    while (!s.isEmpty()) {
        int minIndex = s.indexOf(s.charAt(0));
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(minIndex) && i != minIndex) {
                minIndex = i;
            }
        }
        result += s.charAt(minIndex);
        s = s.substring(0, minIndex) + s.substring(minIndex + 1);
        if (s.isEmpty()) {
            break;
        }

        int maxIndex = s.lastIndexOf(s.charAt(s.length() - 1));
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) > s.charAt(maxIndex) && i != maxIndex) {
                maxIndex = i;
            }
        }
        result += s.charAt(maxIndex);
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);
    }
    return result;
}

