public int minCostClimbingStairs(int[] cost) {
int minCost = 0;
int currentCost = 0;
int i;

for (i = 0; i < cost.length; i++) {
currentCost = Math.min(currentCost + cost[i], cost[i]);
minCost = Math.min(minCost, currentCost);
}

return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];

    if (cost.length == 0) {
        return 0;
    }

    if (cost.length == 1) {
        return cost[0];
    }

    if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int prevCost = 0;
    for (int i = 0; i < cost.length; i++) {
        int currentCost = cost[i];
        if (currentCost < prevCost) {
            minCost += currentCost;
        } else {
            minCost += prevCost;
        }
        prevCost = currentCost;
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int[] memo = new int[cost.length];
    return minCostClimbingStairs(cost, memo, 0, 0);
}

private int minCostClimbingStairs(int[] cost, int[] memo, int index, int costSoFar) {
    if (index >= cost.length) {
        return costSoFar;
    }

    if (memo[index] != 0) {
        return memo[index];
    }

    int minCost = Integer.MAX_VALUE;
    for (int i = index; i < cost.length; i++) {
        minCost = Math.min(minCost, cost[i] + minCostClimbingStairs(cost, memo, i + 1, costSoFar + cost[i]));
    }

    return memo[index] = minCost;
}

