public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int result = 0;
    while (result < n) {
        int minDiff = Integer.MAX_VALUE;
        int x = -1, y = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && Math.abs(arr[i] - arr[j]) < minDiff) {
                    minDiff = Math.abs(arr[i] - arr[j]);
                    x = i;
                    y = j;
                }
            }
        }

        if (minDiff == Integer.MAX_VALUE) {
            break;
        }

        arr[x] -= 1;
        arr[y] += 1;
        result++;
    }

    return result;
}

