public int minOperations(int n) {
	int[] arr = new int[n];
	for (int i = 0; i < n; i++) {
		arr[i] = (2 * i) + 1;
	}

	int minOperations = 0;
	while (true) {
		boolean allEqual = true;
		for (int i = 0; i < n - 1; i++) {
			if (arr[i] != arr[i + 1]) {
				allEqual = false;
				break;
			}
		}
		if (allEqual) {
			return minOperations;
		}

		minOperations++;
		int index1 = 0;
		int index2 = 0;
