		for (int i = 0; i < n; i++) {
			if (arr[i] != arr[i + 1]) {
				int currentDiff = Math.abs(arr[i] - arr[i + 1]);
				if (currentDiff < diff) {
					diff = currentDiff;
					index1 = i;
					index2 = i + 1;
				}
			}
		}
		arr[index1] -= 1;
		arr[index2] += 1;
	}
}

