public int findMinFibonacciNumbers(int k) {
  int[] fib = {1, 1};
  int n = 2;
  int min = Integer.MAX_VALUE;
  while (fib[n - 1] < k) {
    fib[n++] = fib[n - 2] + fib[n - 3];
  }
  for (int i = 0; i < n; i++) {
    if (fib[i] == k) {
      return 1;
    } else if (fib[i] > k) {
      return min < i ? min : i;
    }
  }
  return n;
}

