}

public int findMinFibonacciNumbers(int k) {
    // Initialize the recursive function with the first two Fibonacci numbers
    return findMinFibonacciNumbersRecursive(k, 1, 1, new HashSet<>());
}

private int findMinFibonacciNumbersRecursive(int k, int currentSum, int previousFibonacci, Set<Integer> seenFibonacci) {
    // If the current sum is equal to the given k, return the count of the Fibonacci numbers
    if (currentSum == k) {
        return seenFibonacci.size();
    }

    // If the current sum is greater than the given k, return 0
    if (currentSum > k) {
        return 0;
    }

    // Generate the next Fibonacci number
    int nextFibonacci = previousFibonacci + 1;

    // If the next Fibonacci number is already in the set, skip it
    if (seenFibonacci.contains(nextFibonacci)) {
        return findMinFibonacciNumbersRecursive(k, currentSum, nextFibonacci, seenFibonacci);
    }

    // Add the next Fibonacci number to the set and recurse with the updated sum
    seenFibonacci.add(nextFibonacci);
    return Math.min(
        findMinFibonacciNumbersRecursive(k, currentSum + nextFibonacci, nextFibonacci, seenFibonacci),
        findMinFibonacciNumbersRecursive(k, currentSum, nextFibonacci, seenFibonacci)
    );
}

public int kthFactor(int n, int k) {
    if (n < 1 || k < 1) {
        return -1;
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    return -1;
}

public int kthFactor(int n, int k) {
  // Initialize a list to store the factors of n
  List<Integer> factors = new ArrayList<>();

  // Iterate from 1 to n
  for (int i = 1; i <= n; i++) {
    // If i divides n evenly, add it to the list of factors
    if (n % i == 0) {
      factors.add(i);
    }
  }

  // Check if k is within the range of factors
  if (k - 1 < factors.size()) {
    // Return the kth factor
    return factors.get(k - 1);
  } else {
    // If k is out of range, return -1
    return -1;
  }
}

