public int maxUniqueSplit(String s) {
    // Initialize result as 0
    int result = 0;

    // Go through each character in the string
    for (int i = 0; i < s.length(); i++) {
        // Start of the substring
        int start = i;
        // End of the substring
        int end = i;
        // Set of characters in the substring
        Set<Character> characters = new HashSet<>();

        // Check if the string can be split
        while (end < s.length()) {
            // Add the current character to the set of characters
            characters.add(s.charAt(end));
            // If the set size is greater than 1, it means there are repeated characters
            if (characters.size() > 1) {
                break;
            }
            end++;
        }

        // Check if the substring can be formed
        if (end > start) {
            // Add the length of the substring to the result
            result += (end - start);
        }
    }

    // Return the maximum number of unique substrings
    return result;
}

public int maxUniqueSplit(String s) {
    // Initialize variables to track the maximum number of unique substrings and the current number of unique substrings
    int maxUnique = 0, currUnique = 0;
    // Loop through the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // If the current character is not in the current substring, add it
        if (!s.substring(i).contains(s.substring(i, i + 1))) {
            currUnique++;
        // If the current character is already in the current substring, remove it
        } else {
            currUnique--;
        }
        // Update the maximum number of unique substrings
        maxUnique = Math.max(maxUnique, currUnique);
    }
    return maxUnique + 1;
}

