    List<Integer> steppingNumbers = new ArrayList<>();

    for (int i = low; i <= high; i++) {
        int num = i;
        int prevDigit = -1;
        boolean isSteppingNumber = true;

        while (num > 0) {
            int digit = num % 10;
            if (prevDigit == -1) {
                prevDigit = digit;
            } else {
                if (digit - prevDigit != 1 && digit - prevDigit != -1) {
                    isSteppingNumber = false;
                    break;
                }
                prevDigit = digit;
            }
            num /= 10;
        }

        if (isSteppingNumber) {
            steppingNumbers.add(i);
        }
    }

    steppingNumbers.sort(Integer::compareTo);
    return steppingNumbers;
