public static int squarePermutations(int[] A) {
    // Check if the array is square
    boolean isSquare = true;
    for (int i = 0; i < A.length - 1; i++) {
        if (Math.sqrt(A[i] + A[i + 1]) != (int)Math.sqrt(A[i] + A[i + 1])) {
            isSquare = false;
            break;
        }
    }

    // If the array is not square, return 0
    if (!isSquare) {
        return 0;
    }

    // Sort the array in non-decreasing order
    Arrays.sort(A);

    // Count the number of permutations
    int count = 1;
    for (int i = 0; i < A.length - 1; i++) {
        if (A[i] != A[i + 1]) {
            count++;
        }
    }

    return count;
}

public static int squarePermutations(int[] A) {
