        return 0;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        int sum = 0;
        for (int j = i - 1; j < i + 2; j++) {
            if (j >= 0 && j < A.length) {
                sum += A[j];
            }
        }
        if (sum * sum == A[i]) {
            count++;
        }
    }
    return count;
}

public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<String> permutations = new HashSet<>();

    // Initialize a string buffer to store the current permutation
    StringBuffer currentPermutation = new StringBuffer();

    // Loop through the array and calculate the sum of adjacent elements
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        currentPermutation.append(sum);
    }

    // Append the last element of the array to the current permutation
    currentPermutation.append(A[A.length - 1]);

    // Check if the sum of adjacent elements is a perfect square
    if (currentPermutation.toString().matches("\\d+")) {
        permutations.add(currentPermutation.toString());
    }

    // Return the size of the set, which is the number of square permutations
    return permutations.size();
}

