public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] sum = new int[n];
    for (int i = 1; i < n; i++) {
        sum[i] = sum[i-1] + A[i];
    }
    sum[0] = A[0];
    int count = 0;
    for (int i = 0; i < (1 << n); i++) {
        boolean isSquare = true;
        for (int j = 0; j < n; j++) {
            if (!isSquare(sum[j], i & (1 << j))) {
                isSquare = false;
                break;
            }
        }
        if (isSquare) {
            count++;
        }
    }
    return count;
}

private static boolean isSquare(int sum, int mask) {
    int square = (int)Math.sqrt(sum + 0.5);
    return (square * square == sum) && ((mask & (1 << square)) != 0);
}

public static int largestRectangleArea(int[] heights) {
  if (heights.length == 0) return 0;

  int maxArea = 0;
  int[] left = new int[heights.length];
  int[] right = new int[heights.length];

  for (int i = 0; i < heights.length; i++) {
    int height = heights[i];
    int width = 0;

    for (int j = i - 1; j >= 0; j--) {
      if (height < heights[j]) {
        break;
      }
      width++;
    }
    left[i] = width;

    width = 0;
    for (int j = i + 1; j < heights.length; j++) {
      if (height < heights[j]) {
        break;
      }
      width++;
    }
    right[i] = width;
  }

  for (int i = 0; i < heights.length; i++) {
    int height = heights[i];
    int width = left[i] + right[i] + 1;
    maxArea = Math.max(maxArea, height * width);
  }

  return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    // Sort the heights array in descending order
    Arrays.sort(heights, Collections.reverseOrder());

    // Initialize variables
    int area = 0, currentHeight = 0;

    // Loop through the heights array
    for (int i = 0; i < heights.length; i++) {
        // Update the current height
        currentHeight = heights[i];

        // Calculate the area
        area = Math.max(area, currentHeight * (i + 1));

        // Check if the current height is less than or equal to the previous height
        if (i > 0 && currentHeight <= heights[i - 1]) {
            // Update the area with the maximum area possible
            area = Math.max(area, currentHeight * (i - 1) + area);
        }
    }

    // Return the maximum area
    return area;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Find the rightmost position of each bar on the left side
    for (int i = 0; i < n; i++) {
        for (int j = i; j >= 0; j--) {
            if (heights[j] <= heights[i]) {
                break;
            }
            left[i] = j;
        }
    }

    // Find the leftmost position of each bar on the right side
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) {
            if (heights[j] <= heights[i]) {
                break;
            }
            right[i] = j;
        }
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] - 1) * heights[i]);
    }

    return maxArea;
}

