public static int findSmallestInteger(int n) {
    // Find the smallest integer that can be formed by rearranging the digits of the given positive integer n, which is greater than n.

    // Check if the input is a valid positive integer
    if (n <= 0) {
        return -1;
    }

    // Split the input integer into individual digits
    String digits = String.valueOf(n);

    // Sort the digits in ascending order
    char[] sortedDigits = digits.toCharArray();
    Arrays.sort(sortedDigits);

    // Build the rearranged integer by concatenating the sorted digits
    String rearrangedInteger = new String(sortedDigits);

    // Convert the rearranged integer to an integer
    int rearrangedInt = Integer.parseInt(rearrangedInteger);

    // Check if the rearranged integer is greater than the input integer
    if (rearrangedInt > n) {
        return rearrangedInt;
    } else {
        return -1;
    }
}

