public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            count++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    for (int i = 1; i <= n; i++) {
        int perfectSquare = (int)Math.sqrt(i);
        if (perfectSquare * perfectSquare == i) {
            minSquares++;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 1;
    for (int i = 2; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            count++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int square = (int) Math.sqrt(n);
        if (square * square == n) {
            return count + 1;
        }
        count++;
        n -= square;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    // Initialize a set to store the perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Generate the perfect square numbers from 1 to n
    for (int i = 1; i <= n; i++) {
        perfectSquares.add(i * i);
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minPerfectSquares = n;

    // Iterate over the perfect square numbers and count the number of perfect square numbers that sum up to n
    for (int i = 1; i <= n; i++) {
        if (perfectSquares.contains(n - i)) {
            minPerfectSquares = Math.min(minPerfectSquares, 2);
            break;
        }
    }

    return minPerfectSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversedWords = "";
    for (String word : words) {
        String reversedWord = new StringBuilder(word).reverse().toString();
        reversedWords += reversedWord + " ";
    }
    return reversedWords.trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder();
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord.append(word.charAt(j));
        }
        words[i] = reversedWord.toString();
    }
    return String.join(" ", words);
}

